export class OfflineStore{static PREFIX="school_offline_";static DEFAULT_TTL_MS=12096e5;static isOnline(){return"undefined"==typeof navigator||"boolean"!=typeof navigator.onLine||navigator.onLine}static save(e,t,n){if("undefined"==typeof localStorage||!n)return!1;try{const r=`${this.PREFIX}${e}_${t}`,a={cachedAt:Date.now(),version:"1.0",category:e,id:t,payload:n};return localStorage.setItem(r,JSON.stringify(a)),!0}catch(e){return console.warn("[OfflineStore] Failed to write offline cache (quota exceeded?):",e),!1}}static get(e,t){if("undefined"==typeof localStorage)return null;try{const n=`${this.PREFIX}${e}_${t}`,r=localStorage.getItem(n);if(!r)return null;const a=JSON.parse(r),i=Date.now()-a.cachedAt;return{data:a.payload,cachedAt:a.cachedAt,isOffline:!this.isOnline(),ageMs:i,isExpired:i>this.DEFAULT_TTL_MS}}catch(e){return console.error("[OfflineStore] Error reading cached record:",e),null}}static cacheStudentRecord(e,t){return this.save("student",e,t)}static getStudentRecord(e){return this.get("student",e)}static cacheTeacherRoster(e,t){return this.save("teacher",e,t)}static getTeacherRoster(e){return this.get("teacher",e)}static cacheNotices(e){return this.save("notices","latest",e)}static getCachedNotices(){return this.get("notices","latest")}static renderOfflineBadge(e,t){if(!e)return;const n=e.querySelector(".offline-cache-badge");n&&n.remove();const r=document.createElement("div");r.className="offline-cache-badge flex items-center justify-between bg-amber-500/10 border border-amber-500/30 text-amber-700 px-4 py-2.5 rounded-xl text-xs font-semibold my-3";const a=t?new Date(t).toLocaleDateString():"earlier";r.innerHTML=`\n            <div class="flex items-center gap-2">\n                <i class="fas fa-bolt text-amber-500 animate-pulse"></i>\n                <span>Offline Mode &bull; Showing cached record from ${a}</span>\n            </div>\n            <span class="bg-amber-500/20 px-2 py-0.5 rounded text-[10px] uppercase font-bold tracking-wider">Local Copy</span>\n        `,e.prepend(r)}}"undefined"!=typeof window&&(window.OfflineStore=OfflineStore);